// Generate a descriptive commit message from the git status
async function generateCommitMessage(git) {
  const status = await git.status();
  const added = status.not_added.length + status.created.length;
  const modified = status.modified.length;
  const deleted = status.deleted.length;

  if (added + modified + deleted === 0) {
    return null; // nothing to commit
  }

  // Highlight up to 3 notable files
  const notable = [
    ...status.modified.slice(0, 2),
    ...status.not_added.slice(0, 2),
    ...status.created.slice(0, 2),
  ]
    .slice(0, 3)
    .map((f) => path.basename(f));

  const parts = [];
  if (modified > 0) parts.push(`~${modified}`);
  if (added > 0) parts.push(`+${added}`);
  if (deleted > 0) parts.push(`-${deleted}`);

  const summary = parts.join(' ');
  const files = notable.length > 0 ? ` — ${notable.join(', ')}` : '';
  return `Auto-backup: ${summary}${files}`;
}

