// Map a repo-relative path to a human category label
function categoryFor(relPath) {
  const p = relPath.replace(/\\/g, '/');
  if (p === 'CLAUDE.md') return 'CLAUDE.md';
  if (p === 'settings.json') return 'Settings';
  if (p.startsWith('agents/')) return 'Agents';
  if (p.startsWith('memory/')) return 'Memory';
  if (p.startsWith('rules/')) return 'Rules';
  if (p.startsWith('commands/')) return 'Commands';
  if (p.startsWith('templates/')) return 'Templates';
  if (p.startsWith('projects/')) return 'Projects';
  if (p.startsWith('history/')) return 'History';
  if (p.startsWith('logs/')) return 'Logs';
  return 'Other';
}

// Convert a path to a friendly single-line display name (used in titles when
// exactly one file changed).
function friendlyName(relPath) {
  const p = relPath.replace(/\\/g, '/');
  if (p === 'CLAUDE.md') return 'CLAUDE.md';
  if (p === 'settings.json') return 'settings';
  if (p.startsWith('agents/')) return `agent: ${path.basename(p, '.md')}`;
  if (p.startsWith('rules/')) return `rule: ${path.basename(p, '.md')}`;
  if (p.startsWith('commands/')) return `command: ${path.basename(p, '.md')}`;
  if (p.startsWith('templates/')) return `template: ${path.basename(p, '.md')}`;
  if (p.startsWith('projects/')) {
    // projects/<name>/... — show project + inner path
    const parts = p.split('/');
    return `project: ${parts[1]}/${parts.slice(2).join('/')}`;
  }
  return p;
}

// Derive a verb from the op mix of a list of files
function verbFor(files) {
  const ops = new Set(files.map(f => f.op));
  if (ops.size === 1) {
    if (ops.has('+')) return 'Add';
    if (ops.has('-')) return 'Remove';
  }
  return 'Update';
}

// Build the ≤72-char title line
function buildTitle(all, categories) {
  // Single file → friendly name
  if (all.length === 1) {
    return `${verbFor(all)} ${friendlyName(all[0].path)}`.slice(0, 72);
  }

  const catNames = Object.keys(categories);
  const verb = verbFor(all);

  // Single category
  if (catNames.length === 1) {
    const cat = catNames[0].toLowerCase();
    return `${verb} ${cat} (${all.length} files)`.slice(0, 72);
  }

  // Multiple categories — rank by count desc
  const ranked = catNames
    .map(c => ({ name: c, count: categories[c].length }))
    .sort((a, b) => b.count - a.count);

  // Fit as many category names as possible in budget
  const suffix = ` (${all.length} files)`;
  const budget = 72 - `${verb} `.length - suffix.length;
  const names = [];
  let used = 0;
  for (const r of ranked) {
    const n = r.name.toLowerCase();
    const extra = (names.length === 0 ? n.length : n.length + 3); // " + "
    if (used + extra > budget) break;
    names.push(n);
    used += extra;
  }
  if (names.length === 0) names.push(ranked[0].name.toLowerCase());
  const remaining = ranked.length - names.length;
  const list = names.join(' + ') + (remaining > 0 ? ` + ${remaining} more` : '');
  return `${verb} ${list}${suffix}`.slice(0, 72);
}

// Build the structured body with per-category sections
function buildBody(categories) {
  const MAX_PER_SECTION = 5;
  const sections = [];
  // Sort categories by count desc so the most-changed section shows first
  const ordered = Object.entries(categories).sort((a, b) => b[1].length - a[1].length);

  for (const [cat, files] of ordered) {
    // Sort: modified (~) first, then added (+), then deleted (-)
    const opRank = { '~': 0, '+': 1, '-': 2 };
    const sorted = [...files].sort((a, b) => opRank[a.op] - opRank[b.op]);
    const shown = sorted.slice(0, MAX_PER_SECTION);
    const lines = shown.map(f => `  ${f.op} ${f.path}`);
    if (sorted.length > MAX_PER_SECTION) {
      lines.push(`  ... and ${sorted.length - MAX_PER_SECTION} more`);
    }
    sections.push(`${cat} (${files.length}):\n${lines.join('\n')}`);
  }

  return sections.join('\n\n');
}

// Generate a descriptive commit message from the git status
async function generateCommitMessage(git) {
  const status = await git.status();
  const all = [
    ...status.modified.map(f => ({ path: f, op: '~' })),
    ...status.not_added.map(f => ({ path: f, op: '+' })),
    ...status.created.map(f => ({ path: f, op: '+' })),
    ...status.deleted.map(f => ({ path: f, op: '-' })),
  ];
  if (all.length === 0) return null;

  // Categorize every file
  const categories = {};
  for (const item of all) {
    const cat = categoryFor(item.path);
    if (!categories[cat]) categories[cat] = [];
    categories[cat].push(item);
  }

  const title = buildTitle(all, categories);
  if (all.length === 1) return title;
  return `${title}\n\n${buildBody(categories)}`;
}

