  const clampedPct = Math.min(pct, 110)

  // Status-driven styling
  const statusConfig = {
    healthy: {
      icon: CheckCircle2,
      label: 'Healthy',
      bar: 'bg-emerald-500',
      text: 'text-emerald-500',
